package com.bct.ngtpa.apiservice.application.usecase.session.authenticated;import com.bct.ngtpa.apiservice.application.dto.session.authenticated.*;import com.bct.ngtpa.apiservice.application.port.out.*;import java.time.*;import java.util.*;import reactor.core.publisher.Mono;public final class AuthenticatedSessionLifecycleService {private final AuthenticatedSessionPort port;private final AuthenticatedSessionProtectorPort protector;private final AuthenticatedSessionIdGenerator ids;private final Duration idleTimeout,absoluteTtl;private final Clock clock;public AuthenticatedSessionLifecycleService(AuthenticatedSessionPort port,AuthenticatedSessionProtectorPort protector,AuthenticatedSessionIdGenerator ids,Duration idleTimeout,Duration absoluteTtl,Clock clock){this.port=Objects.requireNonNull(port);this.protector=Objects.requireNonNull(protector);this.ids=Objects.requireNonNull(ids);this.idleTimeout=positive(idleTimeout,"idleTimeout");this.absoluteTtl=positive(absoluteTtl,"absoluteTtl");this.clock=Objects.requireNonNull(clock);}public Mono<AuthenticatedSessionLifecycleResult> create(CreateAuthenticatedSessionCommand c){return Mono.defer(()->{Instant now=clock.instant();Instant absolute=now.plus(absoluteTtl);Instant idle=min(now.plus(idleTimeout),absolute);var session=new AuthenticatedSession(ids.generate(),c.actorContext(),c.accounts(),AuthenticatedSessionStatus.ACTIVE,c.csrfTokenHash(),now,now,idle,absolute);Duration ttl=Duration.between(now,idle);return port.store(new StoreAuthenticatedSessionCommand(session.authenticatedSessionId(),protector.protect(session),ttl,now,c.correlationId())).thenReturn(AuthenticatedSessionLifecycleResult.active(session));});}public Mono<AuthenticatedSessionLifecycleResult> loadAndTouch(LoadAndTouchAuthenticatedSessionCommand c){return port.load(new LoadAuthenticatedSessionCommand(c.authenticatedSessionId(),c.correlationId())).flatMap(optional->{if(optional.isEmpty())return Mono.just(AuthenticatedSessionLifecycleResult.of(AuthenticatedSessionLifecycleStatus.NOT_FOUND));AuthenticatedSession session=protector.unprotect(optional.get());Instant now=clock.instant();if(session.status()!=AuthenticatedSessionStatus.ACTIVE)return Mono.just(AuthenticatedSessionLifecycleResult.of(AuthenticatedSessionLifecycleStatus.REVOKED));if(!session.isUsable(now))return port.delete(new DeleteAuthenticatedSessionCommand(c.authenticatedSessionId(),c.correlationId())).thenReturn(AuthenticatedSessionLifecycleResult.of(AuthenticatedSessionLifecycleStatus.EXPIRED));Instant idle=min(now.plus(idleTimeout),session.absoluteExpiresAt());var touched=new AuthenticatedSession(session.authenticatedSessionId(),session.actorContext(),session.accounts(),session.status(),session.csrfTokenHash(),session.createdAt(),now,idle,session.absoluteExpiresAt());Duration ttl=Duration.between(now,idle);return port.touch(new TouchAuthenticatedSessionCommand(touched.authenticatedSessionId(),protector.protect(touched),ttl,now,c.correlationId())).thenReturn(AuthenticatedSessionLifecycleResult.active(touched));});}public Mono<AuthenticatedSessionLifecycleResult> revoke(RevokeActiveAuthenticatedSessionCommand c){Instant now=clock.instant();return port.revoke(new RevokeAuthenticatedSessionCommand(c.authenticatedSessionId(),now,c.reason(),c.correlationId())).map(x->AuthenticatedSessionLifecycleResult.of(AuthenticatedSessionLifecycleStatus.REVOKED));}private static Duration positive(Duration d,String n){if(d==null||d.isZero()||d.isNegative())throw new IllegalArgumentException(n+" must be positive");return d;}private static Instant min(Instant a,Instant b){return a.isBefore(b)?a:b;}}
